1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects creating an owner who shares a household with an existing owner: same lastName
11	 * AND same address, each compared case-insensitively with collapsed whitespace. A
12	 * collision is rejected 409 via {@link DuplicateHouseholdException}, unless the request
13	 * opts in with {@code sharesHousehold=true}, in which case the check is bypassed.
14	 */
15	public class CheckOwnerHouseholdUnique {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
20	            return;
21	        }
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (sameHousehold(request.getLastName(), request.getAddress(),
24	                    existing.getLastName(), existing.getAddress())) {
25	                throw new DuplicateHouseholdException(
26	                        "An owner with the same last name and address already exists");
27	            }
28	        }
29	    }
30	
31	    /**
32	     * The single source of truth for what "same household" means: identical lastName AND address.
33	     * The lastName is compared case-insensitively with internal whitespace collapsed; the address is
34	     * compared on its normalized form (see {@link NormalizeOwnerAddress#normalize}) so abbreviation,
35	     * case and whitespace differences never split one household. Shared with
36	     * {@link AssignOwnerHousehold} so the 409 bypass and the {@code householdId} assignment can
37	     * never drift on what counts as one household.
38	     */
39	    static boolean sameHousehold(String lastNameA, String addressA, String lastNameB, String addressB) {
40	        return normalize(lastNameA).equals(normalize(lastNameB))
41	                && NormalizeOwnerAddress.normalize(addressA).equals(NormalizeOwnerAddress.normalize(addressB));
42	    }
43	
44	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
45	    static String normalize(String value) {
46	        if (value == null) {
47	            return "";
48	        }
49	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
50	    }
51	}
